import { waveSample,clamp } from './model.js';
const $=id=>document.getElementById(id),reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
const canvas=$('sound-canvas'),draw=canvas.getContext('2d');
let active='color',context,oscillator,gain,starting=false,generation=0,frame=0,phase=0;
function resize(){const b=canvas.getBoundingClientRect(),r=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(b.width*r));canvas.height=Math.max(1,Math.round(b.height*r));draw.setTransform(r,0,0,r,0,0);}
function drawSound(){const {width:w,height:h}=canvas.getBoundingClientRect();if(!w||!h)return;draw.clearRect(0,0,w,h);draw.strokeStyle='#ffffff22';draw.lineWidth=1;for(let i=1;i<6;i++){draw.beginPath();draw.moveTo(0,h*i/6);draw.lineTo(w,h*i/6);draw.stroke();}for(let i=1;i<12;i++){draw.beginPath();draw.moveTo(w*i/12,0);draw.lineTo(w*i/12,h);draw.stroke();}const cycles=Number($('frequency').value)/90,amplitude=h*.34*Number($('volume').value)/20;draw.beginPath();draw.lineWidth=3;draw.strokeStyle='#d4ff55';for(let x=0;x<=w;x++){const y=h/2-waveSample($('wave-type').value,x/w*cycles*Math.PI*2+phase)*amplitude;if(!x)draw.moveTo(x,y);else draw.lineTo(x,y);}draw.stroke();draw.fillStyle='#ffffffbb';draw.font='12px system-ui';draw.fillText('합성 파형 · 가로축은 상대적인 시간',12,h-14);}
function update(){const frequency=clamp($('frequency').value,80,2000),volume=clamp($('volume').value,0,20);$('frequency-output').value=frequency+' Hz';$('volume-output').value=volume+'%';$('wave-caption').textContent=$('wave-type').value.toUpperCase()+' WAVE · '+frequency+' Hz';if(oscillator){oscillator.type=$('wave-type').value;oscillator.frequency.setTargetAtTime(frequency,context.currentTime,.025);gain.gain.setTargetAtTime(volume/400,context.currentTime,.025);}drawSound();}
export function stopSound(){generation++;if(oscillator){gain.gain.cancelScheduledValues(context.currentTime);gain.gain.setTargetAtTime(0,context.currentTime,.015);const old=oscillator,g=gain;old.onended=()=>{old.disconnect();g.disconnect();};old.stop(context.currentTime+.08);oscillator=null;gain=null;}$('sound-toggle').textContent='소리 켜기';$('sound-toggle').setAttribute('aria-pressed','false');$('sound-badge').textContent='소리 꺼짐';drawSound();}
async function toggle(){if(starting)return;if(oscillator){stopSound();return;}const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){$('audio-message').textContent='이 브라우저는 소리 합성을 지원하지 않습니다. 파형 비교는 가능합니다.';return;}starting=true;const token=++generation;$('sound-toggle').disabled=true;try{context??=new Audio();await context.resume();if(token!==generation||active!=='sound'||document.hidden)return;oscillator=context.createOscillator();gain=context.createGain();oscillator.type=$('wave-type').value;oscillator.frequency.value=clamp($('frequency').value,80,2000);gain.gain.value=0;gain.gain.setTargetAtTime(clamp($('volume').value,0,20)/400,context.currentTime,.03);oscillator.connect(gain);gain.connect(context.destination);oscillator.start();$('sound-toggle').textContent='소리 끄기';$('sound-toggle').setAttribute('aria-pressed','true');$('sound-badge').textContent='소리 켜짐';$('audio-message').textContent='기기 음량을 낮추세요. 화면을 옮기면 소리가 꺼집니다.';}catch{stopSound();$('audio-message').textContent='소리를 시작하지 못했습니다. 기기 설정을 확인하세요.';}finally{starting=false;$('sound-toggle').disabled=false;}}
function animate(){frame=0;if(active!=='sound'||document.hidden)return;if(!reducedMotion.matches)phase+=.025;drawSound();if(!reducedMotion.matches)frame=requestAnimationFrame(animate);}
export function selectExperiment(name){if(active!==name)stopSound();active=name;cancelAnimationFrame(frame);if(name==='sound'){resize();update();frame=requestAnimationFrame(animate);}}
$('sound-toggle').addEventListener('click',toggle);for(const id of ['frequency','volume','wave-type'])$(id).addEventListener('input',update);
new ResizeObserver(()=>{if(active==='sound'){resize();drawSound();}}).observe(document.querySelector('main'));
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopSound();cancelAnimationFrame(frame);}else if(active==='sound')frame=requestAnimationFrame(animate);});
window.addEventListener('pagehide',()=>{stopSound();cancelAnimationFrame(frame);});reducedMotion.addEventListener('change',()=>{cancelAnimationFrame(frame);if(active==='sound')frame=requestAnimationFrame(animate);});update();
